.payment-main-fields :deep(.bio-search-select),.payment-main-fields :deep(.bio-search-trigger){width:100%;min-width:0}
.payment-extra-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding-top:10px;border-top:1px solid var(--bio-nexus-color-border);min-width:0}
.payment-extra-fields>*{min-width:0}
